const rtdal006915Source0001 = `sits_regularize <- function(cube, ...) {
    .check_set_caller("sits_regularize")
    # Pre-conditions
    .check_na_null_parameter(cube)
    UseMethod("sits_regularize", cube)
}`

const rtdal006915Source0002 = `sits_regularize.raster_cube <- function(cube, ...,
                                        period,
                                        res,
                                        output_dir,
                                        timeline = NULL,
                                        roi = NULL,
                                        crs = NULL,
                                        tiles = NULL,
                                        grid_system = NULL,
                                        multicores = 2L,
                                        progress = TRUE) {
    # Update token (for big tiffs and slow networks)
    cube <- .cube_token_generator(cube)
    # Preconditions
    .check_raster_cube_files(cube)
    # check period
    .check_period(period)
    # check resolution
    .check_num_parameter(res, exclusive_min = 0.0)
    # check output_dir
    output_dir <- .file_path_expand(output_dir)
    .check_output_dir(output_dir)
    # check multicores
    .check_num_parameter(multicores, min = 1L, max = 2048L)
    # check progress
    progress <- .message_progress(progress)
    # Does cube contain cloud band? If not, issue a warning
    .message_warnings_regularize_cloud(cube)
    # ROI and tiles
    if (.has(roi) || .has(tiles)) {
        .check_roi_tiles(roi, tiles)
    }
    if (.has(roi)) {
        # standardize roi as sf
        roi <- .roi_as_sf(roi, default_crs = crs)

        # get cube as sf
        cube_sf <- .cube_as_sf(cube)

        # check if roi intersects with cube
        .check_that(any(.intersects(cube_sf, roi)))
    }
    if (.has_not(roi) && .has_not(tiles)) {
        roi <- .cube_as_sf(cube)
    }
    # Convert input cube to the user's provided grid system
    if (.has(grid_system)) {
        .check_grid_system(grid_system)
        cube <- suppressWarnings(
            .reg_tile_convert(
                cube = cube,
                grid_system = grid_system,
                roi = roi,
                tiles = tiles
            )
        )
        .check_that(nrow(cube) > 0,
            msg = .conf("messages", "sits_regularize_roi")
        )
    }
    if (.has(timeline)) {
        timeline <- .as_date(timeline)
    }
    # Display warning message in case regularization is done via STAC
    # We prefer to regularize local files
    .message_warnings_regularize_local(cube)
    # Regularize
    .gc_regularize(
        cube = cube,
        timeline = timeline,
        period = period,
        res = res,
        roi = roi,
        tiles = tiles,
        output_dir = output_dir,
        multicores = multicores,
        progress = progress
    )
}`

const rtdal006915Source0003 = `sits_regularize.sar_cube <- function(cube, ...,
                                     period,
                                     res,
                                     output_dir,
                                     timeline = NULL,
                                     grid_system = "MGRS",
                                     roi = NULL,
                                     crs = NULL,
                                     tiles = NULL,
                                     multicores = 2L,
                                     progress = TRUE) {
    # Update token (for big tiffs and slow networks)
    cube <- .cube_token_generator(cube)
    # Preconditions
    .check_raster_cube_files(cube)
    .check_period(period)
    .check_num_parameter(res, exclusive_min = 0.0)
    output_dir <- .file_path_expand(output_dir)
    .check_output_dir(output_dir)
    .check_num_parameter(multicores, min = 1L, max = 2048L)
    progress <- .message_progress(progress)
    if (.has(grid_system)) {
        .check_grid_system(grid_system)
    }
    # deal for ROI and tiles
    if (.has(roi) || .has(tiles)) {
        .check_roi_tiles(roi, tiles)
    }
    if (.has(roi)) {
        roi <- .roi_as_sf(roi, default_crs = crs)
    }
    if (.has_not(roi) && .has_not(tiles)) {
        roi <- .cube_as_sf(cube)
    }
    if (.has(timeline)) {
        timeline <- .as_date(timeline)
    }
    # Convert input sentinel1 cube to the user's provided grid system
    cube <- .reg_tile_convert(
        cube = cube,
        grid_system = grid_system,
        roi = roi,
        tiles = tiles
    )
    .check_that(nrow(cube) > 0,
        msg = .conf("messages", "sits_regularize_roi")
    )
    # Filter tiles
    if (is.character(tiles)) {
        cube <- .cube_filter_tiles(cube, tiles)
    }
    # Display warning message in case STAC cube
    # Prepare parallel processing
    .parallel_start(workers = multicores)
    on.exit(.parallel_stop(), add = TRUE)
    # Call regularize in parallel
    .reg_cube(
        cube = cube,
        timeline = timeline,
        res = res,
        roi = roi,
        period = period,
        output_dir = output_dir,
        progress = progress
    )
}`

const rtdal006915Source0004 = `sits_regularize.combined_cube <- function(cube, ...,
                                          period,
                                          res,
                                          output_dir,
                                          grid_system = NULL,
                                          roi = NULL,
                                          crs = NULL,
                                          tiles = NULL,
                                          multicores = 2L,
                                          progress = TRUE) {
    # Preconditions
    .check_raster_cube_files(cube)
    .check_period(period)
    .check_num_parameter(res, exclusive_min = 0.0)
    output_dir <- .file_path_expand(output_dir)
    .check_output_dir(output_dir)
    .check_num_parameter(multicores, min = 1L, max = 2048L)
    progress <- .message_progress(progress)
    # check for ROI and tiles
    .check_roi_tiles(roi, tiles)
    if (.has(grid_system)) {
        .check_grid_system(grid_system)
    } else if (any("NoTilingSystem" %in% .cube_tiles(cube))) {
        grid_system <- "MGRS"
    }
    # Get a global timeline
    timeline <- .gc_get_valid_timeline(
        cube = cube, period = period
    )
    # Grouping by unique values for each type of cube: sar, optical, etc..
    cubes <- dplyr::group_by(
        cube, .data[["source"]], .data[["collection"]], .data[["satellite"]]
    ) |> dplyr::group_map(~ {
        class(.x) <- .cube_s3class(.x)
        .x
    }, .keep = TRUE)
    # Regularizing each cube
    reg_cubes <- purrr::map(cubes, function(cube) {
        sits_regularize(
            cube = cube,
            timeline = timeline,
            period = period,
            res = res,
            roi = roi,
            crs = crs,
            tiles = tiles,
            output_dir = output_dir,
            grid_system = grid_system,
            multicores = multicores,
            progress = progress
        )
    })
    # In case where more than two cubes need to be merged
    purrr::reduce(reg_cubes, sits_merge)
}`

const rtdal006915Source0005 = `sits_regularize.rainfall_cube <- function(cube, ...,
                                          period,
                                          res,
                                          output_dir,
                                          timeline = NULL,
                                          grid_system = "MGRS",
                                          roi = NULL,
                                          crs = NULL,
                                          tiles = NULL,
                                          multicores = 2L,
                                          progress = TRUE) {
    # Preconditions
    .check_raster_cube_files(cube)
    .check_period(period)
    .check_num_parameter(res, exclusive_min = 0.0)
    output_dir <- .file_path_expand(output_dir)
    .check_output_dir(output_dir)
    .check_num_parameter(multicores, min = 1L, max = 2048L)
    progress <- .message_progress(progress)
    # deal for ROI and tiles
    if (.has(roi) || .has(tiles)) {
        .check_roi_tiles(roi, tiles)
    }
    if (.has(roi)) {
        roi <- .roi_as_sf(roi, default_crs = crs)
    }
    if (.has_not(roi) && .has_not(tiles)) {
        roi <- .cube_as_sf(cube)
    }
    if (.has(grid_system)) {
        .check_grid_system(grid_system)
    }
    if (.has(timeline)) {
        timeline <- .as_date(timeline)
    }
    # Convert input sentinel1 cube to the user's provided grid system
    cube <- .reg_tile_convert(
        cube = cube,
        grid_system = grid_system,
        roi = roi,
        tiles = tiles
    )
    .check_content_data_frame(cube)
    # Filter tiles
    if (is.character(tiles)) {
        cube <- .cube_filter_tiles(cube, tiles)
    }
    # Display warning message in case STAC cube
    # Prepare parallel processing
    .parallel_start(workers = multicores)
    on.exit(.parallel_stop(), add = TRUE)
    # Call regularize in parallel
    .reg_cube(
        cube = cube,
        timeline = timeline,
        res = res,
        roi = roi,
        period = period,
        output_dir = output_dir,
        progress = progress
    )
}`

const rtdal006915Source0006 = `sits_regularize.dem_cube <- function(cube, ...,
                                     res,
                                     output_dir,
                                     grid_system = "MGRS",
                                     roi = NULL,
                                     crs = NULL,
                                     tiles = NULL,
                                     multicores = 2L,
                                     progress = TRUE) {
    # Update token (for big tiffs and slow networks)
    cube <- .cube_token_generator(cube)
    # Preconditions
    .check_raster_cube_files(cube)
    .check_num_parameter(res, exclusive_min = 0L)
    output_dir <- .file_path_expand(output_dir)
    .check_output_dir(output_dir)
    .check_num_parameter(multicores, min = 1L, max = 2048L)
    progress <- .message_progress(progress)
    # ROI and tiles
    if (.has(roi) || .has(tiles)) {
        .check_roi_tiles(roi, tiles)
    }
    if (.has(roi)) {
        roi <- .roi_as_sf(roi, default_crs = crs)
    }
    if (.has_not(roi) && .has_not(tiles)) {
        roi <- .cube_as_sf(cube)
    }
    if (.has(grid_system)) {
        .check_grid_system(grid_system)
    }
    # Convert input sentinel1 cube to the user's provided grid system
    cube <- .reg_tile_convert(
        cube = cube,
        grid_system = grid_system,
        roi = roi,
        tiles = tiles
    )
    .check_content_data_frame(cube)
    # Filter tiles
    if (is.character(tiles)) {
        cube <- .cube_filter_tiles(cube, tiles)
    }
    # DEMs don't have the temporal dimension, so the period is fixed in 1 day.
    period <- "P1D"

    # Display warning message in case STAC cube
    # Prepare parallel processing
    .parallel_start(workers = multicores)
    on.exit(.parallel_stop(), add = TRUE)
    # Call regularize in parallel
    .reg_cube(
        cube = cube,
        timeline = NULL,
        res = res,
        roi = roi,
        period = period,
        output_dir = output_dir,
        progress = progress
    )
}`

const rtdal006915Source0007 = `sits_regularize.ogh_cube <- function(cube, ...,
                                      period,
                                      res,
                                      output_dir,
                                      timeline = NULL,
                                      grid_system = "MGRS",
                                      roi = NULL,
                                      crs = NULL,
                                      tiles = NULL,
                                      multicores = 2L,
                                      progress = TRUE) {
    # Preconditions
    .check_raster_cube_files(cube)
    .check_period(period)
    .check_num_parameter(res, exclusive_min = 0.0)
    output_dir <- .file_path_expand(output_dir)
    .check_output_dir(output_dir)
    .check_num_parameter(multicores, min = 1L, max = 2048L)
    progress <- .message_progress(progress)
    # Manage s2 geometry
    # hold s2 status
    s2_status <- sf::sf_use_s2()
    # Disable for applicable cubes
    cube <- .cube_geometry_use_s2(cube, FALSE)
    # Before exit, restore s2 status
    on.exit(.cube_geometry_use_s2(cube, s2_status))
    # deal for ROI and tiles
    if (.has(roi) || .has(tiles)) {
        .check_roi_tiles(roi, tiles)
    }
    if (.has(roi)) {
        roi <- .roi_as_sf(roi, default_crs = crs)
    }
    if (.has_not(roi) && .has_not(tiles)) {
        roi <- .cube_as_sf(cube)
    }
    if (.has(grid_system)) {
        .check_grid_system(grid_system)
    }
    if (.has(timeline)) {
        timeline <- .as_date(timeline)
    }
    # Convert input sentinel1 cube to the user's provided grid system
    cube <- .reg_tile_convert(
        cube = cube,
        grid_system = grid_system,
        roi = roi,
        tiles = tiles
    )
    .check_content_data_frame(cube)
    # Filter tiles
    if (is.character(tiles)) {
        cube <- .cube_filter_tiles(cube, tiles)
    }
    # Display warning message in case STAC cube
    # Prepare parallel processing
    .parallel_start(workers = multicores)
    on.exit(.parallel_stop(), add = TRUE)
    # Call regularize in parallel
    .reg_cube(
        cube = cube,
        timeline = timeline,
        res = res,
        roi = roi,
        period = period,
        output_dir = output_dir,
        progress = progress
    )
}`

