const rtdal006919Source0001 = `sits_select <- function(data, ...) {
    # set caller to show in errors
    .check_set_caller("sits_select")
    # check data
    .check_na_null_parameter(data)
    # get the meta-type (sits or cube)
    UseMethod("sits_select", data)
}`

const rtdal006919Source0002 = `sits_select.sits <- function(data, ...,
                             bands = NULL,
                             start_date = NULL,
                             end_date = NULL,
                             dates = NULL,
                             labels = NULL) {
    # Pre-condition
    .check_samples_ts(data)
    # Selected raster cube attributes
    data <- .select_sits(
        samples = data,
        bands = bands,
        start_date = start_date,
        end_date = end_date,
        dates = dates,
        labels = labels
    )
    return(data)
}`

const rtdal006919Source0003 = `sits_select.raster_cube <- function(data, ...,
                                    bands = NULL,
                                    start_date = NULL,
                                    end_date = NULL,
                                    dates = NULL,
                                    tiles = NULL) {
    # Update token (for big tiffs and slow networks)
    data <- .cube_token_generator(data)
    # Pre-conditions
    .check_raster_cube_files(data)
    # Selected raster cube attributes
    data <- .select_raster_cube(
        data = data,
        bands = bands,
        start_date = start_date,
        end_date = end_date,
        dates = dates,
        tiles = tiles
    )
    return(data)
}`

const rtdal006919Source0004 = `sits_select.default <- function(data, ...) {
    data <- tibble::as_tibble(data)
    if (all(.conf("sits_cube_cols") %in% colnames(data))) {
        data <- .cube_find_class(data)
    } else if (all(.conf("sits_tibble_cols") %in% colnames(data))) {
        class(data) <- c("sits", class(data))
    } else {
        stop(.conf("messages", "sits_select"))
    }
    sits_select(data, ...)
}`

