const rtdal006920Source0001 = `sits_as_sf <- function(data, ...) {
    .check_set_caller("sits_as_sf")
    UseMethod("sits_as_sf", data)
}`

const rtdal006920Source0002 = `sits_as_sf.sits <- function(data, ..., crs = "EPSG:4326", as_crs = NULL) {
    # Pre-conditions
    .check_samples(data)
    data <- .samples_convert_to_sits(data)
    # Convert samples to sf
    geom <- .point_as_sf(.point(data, crs = crs), as_crs = as_crs)
    # Bind columns
    data <- dplyr::bind_cols(geom, data)
    return(data)
}`

const rtdal006920Source0003 = `sits_as_sf.raster_cube <- function(data, ..., as_crs = NULL) {
    # Pre-conditions
    .check_is_raster_cube(data)
    # Convert cube bbox to sf
    data_sf <- .cube_as_sf(data, as_crs = as_crs)
    dplyr::bind_cols(data_sf, .discard(data, "file_info"))
}`

const rtdal006920Source0004 = `sits_as_sf.vector_cube <- function(data, ..., as_crs = NULL) {
    # Pre-conditions
    .check_is_vector_cube(data)
    # Convert cube bbox to sf
    data_sf <- .cube_as_sf(data, as_crs = as_crs)
    # Bind columns
    dplyr::bind_cols(data_sf, .discard(data, c("file_info", "vector_info")))
}`

