const rtdal006927Source0001 = `sits_as_terra <- function(cube,
                          tile = cube[1L, ]$tile,
                          ...) {
    # Pre-conditions
    .check_set_caller("sits_as_terra")
    .check_is_raster_cube(cube)
    .check_chr_parameter(tile, len_max = 1L)
    .check_chr_contains(cube[["tile"]],
        contains = tile,
        discriminator = "any_of",
        msg = .conf("messages", "sits_as_terra_tile")
    )

    UseMethod("sits_as_terra", cube)
}`

const rtdal006927Source0002 = `sits_as_terra.raster_cube <- function(cube,
                                      tile = cube[1L, ]$tile,
                                      ...,
                                      bands = NULL,
                                      date = NULL) {
    # extract tile from cube
    tile_cube <- .cube_filter_tiles(cube, tile)
    # get file info for tile
    fi <- .fi(tile_cube)

    # filter bands
    if (.has(bands)) {
        .check_cube_bands(tile_cube, bands)
        fi <- .fi_filter_bands(fi, bands)
    } else {
        bands <- .tile_bands(tile_cube)
    }
    # filter dates
    if (.has(date)) {
        .check_dates_timeline(date, tile_cube)
    } else {
        date <- as.Date(.tile_timeline(tile_cube)[[1L]])
    }

    fi <- .fi_filter_dates(fi, date)

    # retrieve files
    image_files <- .fi_paths(fi)

    # export spatial raster
    spatial_raster <- terra::rast(image_files)

    return(spatial_raster)
}`

const rtdal006927Source0003 = `sits_as_terra.probs_cube <- function(cube,
                                     tile = cube[1L, ]$tile,
                                     ...) {
    # extract tile from cube
    tile_cube <- .cube_filter_tiles(cube, tile)
    # get file info for tile
    fi <- .fi(tile_cube)
    # retrieve file
    image_file <- .fi_paths(fi)
    # export spatial raster
    spatial_raster <- terra::rast(image_file)
    # get all labels
    cube_labels <- .tile_labels(tile_cube)
    # save names in terra object
    names(spatial_raster) <- cube_labels
    # return
    return(spatial_raster)
}`

const rtdal006927Source0004 = `sits_as_terra.class_cube <- function(cube,
                                     tile = cube[1L, ]$tile,
                                     ...) {
    # extract tile from cube
    tile_cube <- .cube_filter_tiles(cube, tile)
    # get file info for tile
    fi <- .fi(tile_cube)
    # retrieve file
    image_file <- .fi_paths(fi)
    # create spatial raster
    spatial_raster <- terra::rast(image_file)
    # get all labels
    cube_labels <- .tile_labels(tile_cube)
    # set levels for raster
    terra_levels <- data.frame(
        id = as.numeric(names(cube_labels)),
        cover = unname(cube_labels)
    )
    levels(spatial_raster) <- terra_levels
    # return
    return(spatial_raster)
}`

