const rtdal006978Source0003 = `test_that("Timeline tests", {
    s2_cube <- tryCatch(
        {
            sits_cube(
                source = "AWS",
                collection = "SENTINEL-2-L2A",
                tiles = "20LKP",
                bands = c("B05", "B8A", "CLOUD"),
                start_date = "2019-07-18",
                end_date = "2019-08-30",
                progress = FALSE
            )
        },
        error = function(e) {
            return(NULL)
        }
    )

    testthat::skip_if(
        purrr::is_null(s2_cube),
        "AWS is not accessible"
    )

    tla <- .cube_timeline_acquisition(
        s2_cube,
        origin = as.Date("2019-07-18"),
        period = "P16D"
    )
    expect_s3_class(tla, "tbl_df")
    expect_equal(colnames(tla), c("from_date", "to_date", "20LKP"))
})`

