const rtdal006982Source0015 = `test_that("model seed is available", {
    # MLP
    mlp <- sits_train(
        samples_modis_ndvi, sits_mlp(epochs = 2)
    )

    expect_false(is.null(environment(mlp)[["torch_seed"]]))

    # TAE
    tae <- sits_train(
        samples_modis_ndvi, sits_tae(epochs = 2)
    )

    expect_false(is.null(environment(tae)[["torch_seed"]]))

    # LightTAE
    lighttae <- sits_train(
        samples_modis_ndvi, sits_lighttae(epochs = 2)
    )

    expect_false(is.null(environment(lighttae)[["torch_seed"]]))

    # ResNet
    resnet <- sits_train(
        samples_modis_ndvi, sits_resnet(epochs = 2)
    )

    expect_false(is.null(environment(resnet)[["torch_seed"]]))

    # TempCNN
    tempcnn <- sits_train(
        samples_modis_ndvi, sits_tempcnn(epochs = 2)
    )

    expect_false(is.null(environment(tempcnn)[["torch_seed"]]))
})`

const rtdal006982Source0016 = `test_that("normalization new version", {
    #
    # New normalization
    #
    stats <- .samples_stats(cerrado_2classes)

    # In new version only predictors can be normalized
    preds <- .predictors(cerrado_2classes)

    # Now, 'norm1' is a normalized predictors
    preds_norm <- .pred_normalize(preds, stats)

    # From predictors, get feature values
    values <- .pred_features(preds)
    values_norm <- .pred_features(preds_norm)

    # Normalized data should have minimum value between
    #   0.0001 (inclusive) and abs(min(values))
    expect_true(1e-4 <= min(values_norm) && min(values_norm) < abs(min(values)))

    # Normalized data should have maximum value between
    #   abs(max(values)) and 1.0 (inclusive)
    expect_true(abs(max(values)) < max(values_norm) && max(values_norm) <= 1.0)
})`

