const rtdal007052Source0020 = "test_that(\"can use `%m-%` and `add_with_rollback()` to solve month rollback issues\", {\n  requireNamespace(\"lubridate\", quietly = TRUE)\n  `%m-%` <- lubridate::`%m-%`\n\n  i <- vec_c(as.Date(\"2019-02-27\") + 0:3, as.Date(\"2019-03-27\") + 0:5)\n  x <- seq_along(i)\n\n  starts <- i %m-% months(1)\n  stops <- i\n\n  # 3/27 rollback to 2/27\n  # 3/28 rollback to 2/28\n  # 3/29 rollback to 2/28\n  # 3/30 rollback to 2/28\n  # 3/31 rollback to 2/28\n  # 4/01 rollback to 3/01\n  expect_equal(\n    hop_index(x, i, starts, stops, identity),\n    list(\n      1L,\n      1:2,\n      1:3,\n      1:4,\n      1:5,\n      2:6,\n      2:7,\n      2:8,\n      2:9,\n      3:10\n    )\n  )\n\n  starts <- lubridate::add_with_rollback(i, -months(1), roll_to_first = TRUE)\n  stops <- i\n\n  # 3/27 rollback to 2/27\n  # 3/28 rollback to 2/28\n  # 3/29 rollback to 2/28 then forward to 3/01\n  # 3/30 rollback to 2/28 then forward to 3/01\n  # 3/31 rollback to 2/28 then forward to 3/01\n  # 4/01 rollback to 3/01\n  expect_equal(\n    hop_index(x, i, starts, stops, identity),\n    list(\n      1L,\n      1:2,\n      1:3,\n      1:4,\n      1:5,\n      2:6,\n      3:7,\n      3:8,\n      3:9,\n      3:10\n    )\n  )\n})"

const rtdal007052Source0021 = `test_that("can order by two vectors using a data frame", {
  i <- data.frame(
    date1 = new_date(c(0, 3, 4, 5)),
    date2 = new_date(c(0, 1, 2, 4))
  )

  before <- data.frame(date1 = 2, date2 = 1)
  starts <- i - vec_recycle(before, vec_size(i))

  stops <- i

  # NOTE - This is a bit tricky. It always tries to determine the comparison
  # order using the first column that it comes across. If the values are equal,
  # only then will it look to the second column

  expect_equal(
    hop_index(i, i, starts, stops, ~.x),
    list(
      # At row 1, subtracting makes no difference
      # Return row 1
      vec_slice(i, 1L),

      # "1970-01-04" - 2 days = "1970-01-02"
      # "1970-01-02" > "1970-01-01". Done.
      # Return row 2
      vec_slice(i, 2L),

      # "1970-01-05" - 2 days = "1970-01-03"
      # "1970-01-03" < "1970-01-04" so use row 2
      # "1970-01-03" > "1970-01-01" so don't use row 1
      # Return row 2 and 3
      vec_slice(i, 2:3),

      # "1970-01-06" - 2 days = "1970-01-04"
      # "1970-01-04" < "1970-01-05" so use row 3
      # "1970-01-04" = "1970-01-04" so look to column 2
      # "1970-01-05" - 1 day = "1970-01-04" (col 2)
      # "1970-01-04" > "1970-01-02" so don't use row 2
      # Return row 3 and 4
      vec_slice(i, 3:4)
    )
  )
})`

const rtdal007052Source0022 = `test_that("can use a data frame index where the first column breaks ties (#133)", {
  i <- vec_c(
    data.frame(year = 2019, month = c(4, 5, 5, 6, 7, 8)),
    data.frame(year = 2020, month = 1:4)
  )
  starts <- data.frame(year = 2019, month = 5:6)
  stops <- data.frame(year = 2020, month = 2:3)

  expect_identical(
    hop_index(i, i, starts, stops, identity),
    list(
      vec_slice(i, 2:8),
      vec_slice(i, 4:9)
    )
  )
})`

const rtdal007052Source0023 = `test_that("can select no rows when using a data frame index", {
  i <- data.frame(year = 2020, month = 2)
  starts <- data.frame(year = 2020, month = 3)
  stops <- data.frame(year = 2020, month = 4)

  expect_identical(
    hop_index(i, i, starts, stops, identity),
    list(vec_slice(i, NULL))
  )
})`

