const rtdal007053Source0001 = `test_that("hop_index2_vec() works", {
  expect_identical(hop_index2_vec(1L, 1L, 1, 1, 1, ~ .x + .y), 2L)
})`

const rtdal007053Source0002 = `test_that("hop_index2_vec() doesn't retains names of x (#75)", {
  expect_named(hop_index2_vec(c(x = 1L), c(y = 1L), 1, 1, 1, ~ .x + .y), NULL)
})`

const rtdal007053Source0003 = `test_that("hop_index2_vec() can simplify automatically", {
  expect_identical(hop_index2_vec(1, 2, 1, 1, 1, ~ .x + .y, .ptype = NULL), 3)
})`

const rtdal007053Source0004 = `test_that("hop_index2_vec() errors if it can't simplify", {
  fn <- function(x, y) {
    if (x == 1L) {
      1
    } else {
      "hi"
    }
  }

  expect_snapshot({
    (expect_error(
      hop_index2_vec(1:2, 1:2, 1:2, 1:2, 1:2, fn, .ptype = NULL),
      class = "vctrs_error_incompatible_type"
    ))
  })
})`

const rtdal007053Source0005 = "test_that(\"`.ptype = NULL` validates that element lengths are 1\", {\n  expect_snapshot(error = TRUE, {\n    hop_index2_vec(\n      1:2,\n      1:2,\n      1:2,\n      1:2,\n      1:2,\n      ~ if (.x == 1L) {\n        1:2\n      } else {\n        1\n      },\n      .ptype = NULL\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    hop_index2_vec(\n      1:2,\n      1:2,\n      1:2,\n      1:2,\n      1:2,\n      ~ if (.x == 1L) {\n        NULL\n      } else {\n        2\n      },\n      .ptype = NULL\n    )\n  })\n})"

const rtdal007053Source0006 = "test_that(\"size 0 `.starts` / `.stops` returns size 0 `.ptype`\", {\n  expect_identical(\n    hop_index2_vec(1:5, 1:5, 1:5, integer(), integer(), ~.x, .ptype = NULL),\n    NULL\n  )\n  expect_identical(\n    hop_index2_vec(1:5, 1:5, 1:5, integer(), integer(), ~.x, .ptype = double()),\n    double()\n  )\n})"

const rtdal007053Source0007 = "test_that(\"`hop_index2_vec()` falls back to `c()` method as required\", {\n  local_c_foobar()\n\n  expect_identical(\n    hop_index2_vec(\n      1:3,\n      1:3,\n      1:3,\n      1:3,\n      1:3,\n      ~ foobar(.x),\n      .ptype = foobar(integer())\n    ),\n    foobar(1:3)\n  )\n  expect_condition(\n    hop_index2_vec(\n      1:3,\n      1:3,\n      1:3,\n      1:3,\n      1:3,\n      ~ foobar(.x),\n      .ptype = foobar(integer())\n    ),\n    class = \"slider_c_foobar\"\n  )\n\n  expect_identical(\n    hop_index2_vec(1:3, 1:3, 1:3, 1:3, 1:3, ~ foobar(.x)),\n    foobar(1:3)\n  )\n  expect_condition(\n    hop_index2_vec(1:3, 1:3, 1:3, 1:3, 1:3, ~ foobar(.x)),\n    class = \"slider_c_foobar\"\n  )\n})"

