const rtdal007056Source0015 = "test_that(\"`.starts` and `.stops` must be integerish\", {\n  expect_snapshot({\n    (expect_error(\n      hop(1, \"x\", 1, identity),\n      class = \"vctrs_error_subscript_type\"\n    ))\n    (expect_error(\n      hop(1, 1, \"x\", identity),\n      class = \"vctrs_error_subscript_type\"\n    ))\n  })\n})"

const rtdal007056Source0016 = "test_that(\"`error_call` and `.error_call` args aren't swallowed\", {\n  fn <- function(x, error_call) {\n    abort(\"hi\", call = error_call)\n  }\n  fn_dot <- function(x, .error_call) {\n    abort(\"hi\", call = .error_call)\n  }\n\n  expect_snapshot(error = TRUE, {\n    hop(1, 1, 1, fn, error_call = call(\"foo\"))\n  })\n  expect_snapshot(error = TRUE, {\n    hop(1, 1, 1, fn_dot, .error_call = call(\"foo\"))\n  })\n})"

const rtdal007056Source0017 = `test_that("names exist on inner sliced elements", {
  names <- letters[1:5]
  x <- set_names(1:5, names)
  exp <- as.list(names)
  expect_equal(hop(x, 1:5, 1:5, ~ names(.x)), exp)
})`

const rtdal007056Source0018 = `test_that("names are never placed on the output", {
  x <- set_names(1:5, letters[1:5])
  expect_null(names(hop(x, 1:5, 1:5, ~.x)))
})`

