const rtdal007067Source0001 = `test_that("pslide_*() works", {
  expect_identical(pslide_vec(list(1L, 1L), ~ .x + .y), 2L)
  expect_identical(pslide_int(list(1L, 1L), ~ .x + .y), 2L)
})`

const rtdal007067Source0002 = `test_that("pslide_*() retains names of first input", {
  expect_identical(pslide_vec(list(c(x = 1L), c(y = 1L)), ~ .x + .y), c(x = 2L))
  expect_identical(pslide_int(list(c(x = 1L), c(y = 1L)), ~ .x + .y), c(x = 2L))
})`

const rtdal007067Source0003 = `test_that("pslide_vec() can simplify automatically", {
  expect_identical(pslide_vec(list(1, 2), ~ .x + .y, .ptype = NULL), 3)
})`

const rtdal007067Source0004 = `test_that("pslide_vec() errors if it can't simplify", {
  fn <- function(x, y) {
    if (x == 1L) {
      1
    } else {
      "hi"
    }
  }
  expect_snapshot({
    (expect_error(
      pslide_vec(list(1:2, 1:2), fn, .ptype = NULL),
      class = "vctrs_error_incompatible_type"
    ))
  })
})`

