const rtdal007071Source0001 = `test_that("slide_index2_*() works", {
  expect_identical(slide_index2_vec(1L, 1L, 1, ~ .x + .y), 2L)
  expect_identical(slide_index2_int(1L, 1L, 1, ~ .x + .y), 2L)
})`

const rtdal007071Source0002 = `test_that("slide_index2_*() retains names of x", {
  expect_identical(
    slide_index2_vec(c(x = 1L), c(y = 1L), 1, ~ .x + .y),
    c(x = 2L)
  )
  expect_identical(
    slide_index2_int(c(x = 1L), c(y = 1L), 1, ~ .x + .y),
    c(x = 2L)
  )
})`

const rtdal007071Source0003 = `test_that("slide_index2_vec() can simplify automatically", {
  expect_identical(slide_index2_vec(1, 2, 1, ~ .x + .y, .ptype = NULL), 3)
})`

const rtdal007071Source0004 = `test_that("slide_index2_*() errors if it can't simplify", {
  fn <- function(x, y) {
    if (x == 1L) {
      1
    } else {
      "hi"
    }
  }
  expect_snapshot({
    (expect_error(
      slide_index2_vec(1:2, 1:2, 1:2, fn, .ptype = NULL),
      class = "vctrs_error_incompatible_type"
    ))
  })
  expect_snapshot({
    (expect_error(
      slide_index2_int(1:2, 1:2, 1:2, fn),
      class = "vctrs_error_incompatible_type"
    ))
  })
})`

