const rtdal007074Source0001 = `test_that("basic call works", {
  expect_equal(
    slide_period(1, as.Date("2019-01-01"), "year", identity),
    list(1)
  )
})`

const rtdal007074Source0002 = "test_that(\"`.x` must be a vector\", {\n  expect_snapshot({\n    (expect_error(slide_period(call(\"fn\")), class = \"vctrs_error_scalar_type\"))\n  })\n})"

const rtdal007074Source0003 = `test_that(".x must be the same size as .i", {
  expect_snapshot({
    (expect_error(
      slide_period(1, new_date(c(1, 2)), "year", identity),
      class = "slider_error_index_incompatible_size"
    ))
  })
})`

const rtdal007074Source0004 = `test_that(".i must be ascending", {
  expect_snapshot({
    (expect_error(
      slide_period(1:2, new_date(c(2, 1)), "year", identity),
      class = "slider_error_index_must_be_ascending"
    ))
  })
})`

const rtdal007074Source0005 = `test_that("empty input returns a list, but after the index size check", {
  expect_equal(slide_period(integer(), new_date(), "year", ~.x), list())
  expect_snapshot({
    (expect_error(
      slide_period(integer(), new_date(0), "year", ~.x),
      class = "slider_error_index_incompatible_size"
    ))
  })
})`

const rtdal007074Source0006 = "test_that(\"empty input works with `.complete = TRUE` (#111)\", {\n  expect_equal(\n    slide_period(integer(), new_date(), \"year\", ~.x, .complete = TRUE),\n    list()\n  )\n})"

const rtdal007074Source0007 = `test_that(".i must not contain NA values", {
  expect_snapshot({
    (expect_error(
      slide_period(1:2, new_date(c(1, NA)), "year", identity),
      class = "slider_error_index_cannot_be_na"
    ))
    (expect_error(
      slide_period(1:2, new_date(c(NA, 1)), "year", identity),
      class = "slider_error_index_cannot_be_na"
    ))
  })
})`

const rtdal007074Source0008 = "test_that(\"`.before` works\", {\n  expect_equal(\n    slide_period(1:2, new_date(c(30, 31)), \"month\", identity, .before = 1),\n    list(1, c(1, 2))\n  )\n})"

const rtdal007074Source0009 = "test_that(\"`.before` skips over irregular period gaps\", {\n  i <- as.Date(c(\"2019-01-01\", \"2019-02-01\", \"2019-04-01\"))\n\n  expect_equal(\n    slide_period(1:3, i, \"month\", identity, .before = 1),\n    list(1, 1:2, 3)\n  )\n\n  expect_equal(\n    slide_period(1:3, i, \"month\", identity, .before = 2),\n    list(1, 1:2, 2:3)\n  )\n})"

const rtdal007074Source0010 = "test_that(\"`.before` set to Inf works\", {\n  i <- as.Date(c(\"2019-01-01\", \"2019-02-01\", \"2019-04-01\"))\n\n  expect_equal(\n    slide_period(1:3, i, \"month\", identity, .before = Inf),\n    list(1, 1:2, 1:3)\n  )\n})"

const rtdal007074Source0011 = "test_that(\"can use negative `.before`\", {\n  i <- as.Date(c(\"2019-01-01\", \"2019-02-01\", \"2019-04-01\"))\n\n  expect_equal(\n    slide_period(1:3, i, \"month\", identity, .before = -1, .after = 1),\n    list(2, integer(), integer())\n  )\n})"

const rtdal007074Source0012 = "test_that(\"`.before` range cannot be after `.after` range\", {\n  i <- as.Date(c(\"2019-01-01\", \"2019-02-01\", \"2019-04-01\"))\n\n  expect_snapshot(error = TRUE, {\n    slide_period(1:3, i, \"month\", identity, .before = -1)\n  })\n})"

const rtdal007074Source0013 = "test_that(\"`.before` cannot be NA\", {\n  expect_snapshot(error = TRUE, {\n    slide_period(1, new_date(0), \"year\", identity, .before = NA_integer_)\n  })\n})"

