const rtdal007075Source0001 = "test_that(\"size of each `.f` result must be 1\", {\n  expect_snapshot(error = TRUE, {\n    slide_period2_vec(1:2, 1:2, new_date(c(1, 2)), \"day\", ~ c(.x, .y))\n  })\n  expect_snapshot(error = TRUE, {\n    slide_period2_int(1:2, 1:2, new_date(c(1, 2)), \"day\", ~ c(.x, .y))\n  })\n})"

const rtdal007075Source0002 = `test_that("inner type is allowed to be different", {
  expect_equal(
    slide_period2_vec(
      1:2,
      1:2,
      new_date(c(1, 2)),
      "day",
      ~ if (.x == 1L) {
        list(1)
      } else {
        list("hi")
      },
      .ptype = list()
    ),
    list(1, "hi")
  )
})`

const rtdal007075Source0003 = `test_that("inner type can be restricted with list_of", {
  expect_snapshot({
    (expect_error(
      slide_period2_vec(
        1:2,
        1:2,
        new_date(c(1, 2)),
        "day",
        ~ if (.x == 1L) {
          list_of(1)
        } else {
          list_of("hi")
        },
        .ptype = list_of(.ptype = double())
      ),
      class = "vctrs_error_incompatible_type"
    ))
  })
})`

