const rtdal007077Source0001 = "test_that(\"size of each `.f` result must be 1\", {\n  expect_snapshot(error = TRUE, slide_vec(1:2, ~ c(.x, 1)))\n})"

const rtdal007077Source0002 = "test_that(\"size of each `.f` result must be 1\", {\n  expect_snapshot(error = TRUE, slide_dbl(1:2, ~ c(.x, 1)))\n})"

const rtdal007077Source0003 = `test_that("inner type is allowed to be different", {
  expect_equal(
    slide_vec(
      1:2,
      ~ if (.x == 1L) {
        list(1)
      } else {
        list("hi")
      },
      .ptype = list()
    ),
    list(1, "hi")
  )
})`

const rtdal007077Source0004 = `test_that("inner type can be restricted with list_of", {
  expect_snapshot({
    (expect_error(
      slide_vec(
        1:2,
        ~ if (.x == 1L) {
          list_of(1)
        } else {
          list_of("hi")
        },
        .ptype = list_of(.ptype = double())
      ),
      class = "vctrs_error_incompatible_type"
    ))
  })
})`

const rtdal007077Source0005 = `test_that("inner type can be restricted", {
  expect_snapshot({
    (expect_error(
      slide_dbl(
        1:2,
        ~ if (.x == 1L) {
          1
        } else {
          "x"
        }
      ),
      class = "vctrs_error_incompatible_type"
    ))
  })
})`

const rtdal007077Source0006 = `test_that(".ptype is respected", {
  expect_equal(slide_vec(1, ~.x), 1)
  expect_equal(slide_vec(1, ~.x, .ptype = int()), 1L)
  expect_snapshot({
    (expect_error(
      slide_vec(1, ~ .x + .5, .ptype = integer()),
      class = "vctrs_error_cast_lossy"
    ))
  })
})`

const rtdal007077Source0007 = "test_that(\"`.ptype = NULL` results in 'guessed' .ptype\", {\n  expect_equal(\n    slide_vec(1, ~.x, .ptype = NULL),\n    slide_vec(1, ~.x, .ptype = dbl())\n  )\n})"

const rtdal007077Source0008 = "test_that(\"`.ptype = NULL` fails if no common type is found\", {\n  expect_snapshot({\n    (expect_error(\n      slide_vec(1:2, ~ ifelse(.x == 1L, \"hello\", 1), .ptype = NULL),\n      class = \"vctrs_error_incompatible_type\"\n    ))\n  })\n})"

const rtdal007077Source0009 = "test_that(\"`.ptype = NULL` validates that element lengths are 1\", {\n  expect_snapshot(error = TRUE, {\n    slide_vec(\n      1:2,\n      ~ if (.x == 1L) {\n        1:2\n      } else {\n        1\n      },\n      .ptype = NULL\n    )\n  })\n})"

const rtdal007077Source0010 = "test_that(\"`.ptype = NULL` returns `NULL` with size 0 `.x`\", {\n  expect_equal(slide_vec(integer(), ~.x, .ptype = NULL), NULL)\n})"

