const rtdal007077Source0012 = `test_that(".ptypes with a vec_proxy() are restored to original type", {
  expect_s3_class(
    slide_vec(Sys.Date() + 1:5, ~.x, .ptype = as.POSIXlt(Sys.Date())),
    "POSIXlt"
  )
})`

const rtdal007077Source0013 = `test_that("can return a matrix and rowwise bind the results together", {
  mat <- matrix(1, ncol = 2)
  expect_equal(
    slide_vec(1:5, ~mat, .ptype = mat),
    rbind(mat, mat, mat, mat, mat)
  )
})`

const rtdal007077Source0014 = "test_that(\"`slide_vec()` falls back to `c()` method as required\", {\n  local_c_foobar()\n\n  expect_identical(\n    slide_vec(1:3, ~ foobar(.x), .ptype = foobar(integer())),\n    foobar(1:3)\n  )\n  expect_condition(\n    slide_vec(1:3, ~ foobar(.x), .ptype = foobar(integer())),\n    class = \"slider_c_foobar\"\n  )\n\n  expect_identical(slide_vec(1:3, ~ foobar(.x)), foobar(1:3))\n  expect_condition(slide_vec(1:3, ~ foobar(.x)), class = \"slider_c_foobar\")\n})"

const rtdal007077Source0015 = "test_that(\".step produces typed `NA` values\", {\n  expect_identical(slide_int(1:3, identity, .step = 2), c(1L, NA, 3L))\n  expect_identical(slide_dbl(1:3, identity, .step = 2), c(1, NA, 3))\n  expect_identical(\n    slide_chr(c(\"a\", \"b\", \"c\"), identity, .step = 2),\n    c(\"a\", NA, \"c\")\n  )\n  expect_identical(slide_vec(1:3, identity, .step = 2), c(1L, NA, 3L))\n  expect_identical(\n    slide_vec(1:3, identity, .step = 2, .ptype = integer()),\n    c(1L, NA, 3L)\n  )\n})"

const rtdal007077Source0016 = "test_that(\".complete produces typed `NA` values\", {\n  expect_identical(\n    slide_int(1:3, ~1L, .before = 1, .complete = TRUE),\n    c(NA, 1L, 1L)\n  )\n  expect_identical(\n    slide_dbl(1:3, ~1, .before = 1, .complete = TRUE),\n    c(NA, 1, 1)\n  )\n  expect_identical(\n    slide_chr(1:3, ~\"1\", .before = 1, .complete = TRUE),\n    c(NA, \"1\", \"1\")\n  )\n  expect_identical(\n    slide_vec(1:3, ~1, .before = 1, .complete = TRUE),\n    c(NA, 1, 1)\n  )\n  expect_identical(\n    slide_vec(1:3, ~1, .before = 1, .complete = TRUE, .ptype = integer()),\n    c(NA, 1L, 1L)\n  )\n})"

const rtdal007077Source0017 = `test_that("names exist on inner sliced elements", {
  names <- letters[1:5]
  x <- set_names(1:5, names)
  exp <- set_names(as.list(names), names)
  expect_equal(slide_vec(x, ~ list(names(.x))), exp)
})`

const rtdal007077Source0018 = `test_that("names can be placed on atomics", {
  names <- letters[1:5]
  x <- set_names(1:5, names)
  expect_equal(names(slide_vec(x, ~.x)), names)
  expect_equal(names(slide_vec(x, ~.x, .ptype = int())), names)
  expect_equal(names(slide_vec(x, ~.x, .ptype = dbl())), names)
  expect_equal(names(slide_int(x, ~.x)), names)
  expect_equal(names(slide_dbl(x, ~.x)), names)
})`

const rtdal007077Source0019 = "test_that(\"names from `.x` are kept, and new names from `.f` results are dropped\", {\n  x <- set_names(1, \"x\")\n\n  expect_identical(slide_vec(x, ~ c(y = 2), .ptype = NULL), c(x = 2))\n  expect_identical(slide_vec(1, ~ c(y = 2), .ptype = NULL), 2)\n\n  expect_identical(slide_dbl(x, ~ c(y = 2)), c(x = 2))\n  expect_identical(slide_dbl(1, ~ c(y = 2)), 2)\n})"

const rtdal007077Source0020 = `test_that("names can be placed on data frames", {
  names <- letters[1:2]
  x <- set_names(1:2, names)

  out <- slide_vec(x, ~ data.frame(x = .x))
  expect_equal(rownames(out), names)

  out <- slide_vec(x, ~ data.frame(x = .x), .ptype = data.frame(x = int()))
  expect_equal(rownames(out), names)
})`

const rtdal007077Source0021 = `test_that("names can be placed on arrays", {
  names <- letters[1:2]
  x <- set_names(1:2, names)
  out <- slide_vec(
    x,
    ~ array(.x, c(1, 1)),
    .ptype = array(int(), dim = c(0, 1))
  )
  expect_equal(rownames(out), names)
})`

const rtdal007077Source0022 = `test_that("names can be placed correctly on proxied objects", {
  names <- letters[1:2]
  x <- set_names(1:2, names)
  datetime_lt <- as.POSIXlt(new_datetime(0))
  out <- slide_vec(x, ~datetime_lt, .ptype = datetime_lt)
  expect_equal(names(out), names)
})`

