const rtdal007078Source0032 = `test_that("cannot use invalid .step", {
  expect_snapshot(error = TRUE, slide(1, identity, .step = -1))
  expect_snapshot(error = TRUE, slide(1, identity, .step = 0))

  expect_snapshot(error = TRUE, slide(1, identity, .step = c(1, 2)))
  expect_snapshot({
    (expect_error(
      slide(1, identity, .step = "x"),
      class = "vctrs_error_incompatible_type"
    ))
  })
})`

const rtdal007078Source0033 = `test_that("cannot use invalid .complete", {
  expect_snapshot(error = TRUE, slide(1, identity, .complete = c(TRUE, TRUE)))
  expect_snapshot({
    (expect_error(
      slide(1, identity, .complete = "hi"),
      class = "vctrs_error_incompatible_type"
    ))
  })
})`

const rtdal007078Source0034 = `test_that("slide() forces arguments in the same way as base R / map()", {
  f_slide <- slide(1:2, function(i) function(x) x + i)
  f_base <- lapply(1:2, function(i) function(x) x + i)

  expect_equal(f_slide[[1]](0), f_base[[1]](0))
  expect_equal(f_slide[[2]](0), f_base[[2]](0))
})`

const rtdal007078Source0035 = "test_that(\n  paste0(\n    \"proof that the `window_stop < window_start` check is required for \",\n    \"cases where the window is completely OOB\"\n  ),\n  {\n    expect_equal(\n      slide(1:3, identity, .before = 4, .after = -4),\n      list(integer(), integer(), integer())\n    )\n  }\n)"

const rtdal007078Source0036 = "test_that(\"`error_call` and `.error_call` args aren't swallowed\", {\n  fn <- function(x, error_call) {\n    abort(\"hi\", call = error_call)\n  }\n  fn_dot <- function(x, .error_call) {\n    abort(\"hi\", call = .error_call)\n  }\n\n  expect_snapshot(error = TRUE, {\n    slide(1, fn, error_call = call(\"foo\"))\n  })\n  expect_snapshot(error = TRUE, {\n    slide(1, fn_dot, .error_call = call(\"foo\"))\n  })\n})"

