const rtdal007079Source0001 = `test_that("slide2_*() works", {
  expect_identical(slide2_vec(1L, 1L, ~ .x + .y), 2L)
  expect_identical(slide2_int(1L, 1L, ~ .x + .y), 2L)
})`

const rtdal007079Source0002 = `test_that("slide2_*() retains names of x", {
  expect_identical(slide2_vec(c(x = 1L), c(y = 1L), ~ .x + .y), c(x = 2L))
  expect_identical(slide2_int(c(x = 1L), c(y = 1L), ~ .x + .y), c(x = 2L))
})`

const rtdal007079Source0003 = `test_that("slide2_vec() can simplify automatically", {
  expect_identical(slide2_vec(1, 2, ~ .x + .y, .ptype = NULL), 3)
})`

const rtdal007079Source0004 = `test_that("slide2_vec() errors if it can't simplify", {
  fn <- function(x, y) {
    if (x == 1L) {
      1
    } else {
      "hi"
    }
  }
  expect_snapshot({
    (expect_error(
      slide2_vec(1:2, 1:2, fn, .ptype = NULL),
      class = "vctrs_error_incompatible_type"
    ))
  })
})`

const rtdal007079Source0005 = `test_that("slide2_*() errors if it can't cast", {
  fn <- function(x, y) {
    if (x == 1L) {
      1
    } else {
      "hi"
    }
  }
  expect_snapshot({
    (expect_error(
      slide2_int(1:2, 1:2, fn),
      class = "vctrs_error_incompatible_type"
    ))
  })
})`

const rtdal007079Source0006 = `test_that("slide2_int() works", {
  expect_identical(slide2_int(1L, 1L, ~ .x + .y), 2L)
})`

const rtdal007079Source0007 = `test_that("slide2_int() can coerce", {
  expect_identical(slide2_int(1, 1, ~ .x + .y), 2L)
})`

const rtdal007079Source0008 = `test_that("slide2_dbl() works", {
  expect_identical(slide2_dbl(1, 1, ~.x), 1)
})`

const rtdal007079Source0009 = `test_that("slide2_dbl() can coerce", {
  expect_identical(slide2_dbl(1L, 1L, ~ .x + .y), 2)
})`

const rtdal007079Source0010 = `test_that("slide2_chr() works", {
  expect_identical(slide2_chr("x", 1, ~.x), "x")
})`

const rtdal007079Source0011 = `test_that("slide2_chr() cannot coerce", {
  expect_snapshot({
    (expect_error(
      slide2_chr(1, 1, ~ .x + .y),
      class = "vctrs_error_incompatible_type"
    ))
  })
})`

const rtdal007079Source0012 = `test_that("slide2_lgl() works", {
  expect_identical(slide2_lgl(TRUE, 1, ~.x), TRUE)
})`

const rtdal007079Source0013 = `test_that("slide2_lgl() can coerce", {
  expect_identical(slide2_lgl(1, 0, ~ .x + .y), TRUE)
})`

const rtdal007079Source0014 = `test_that("slide2_dfr() works", {
  expect_identical(
    slide2_dfr(
      1:2,
      1:2,
      ~ new_data_frame(list(x = list(.x), y = list(.y))),
      .before = 1
    ),
    data_frame(
      x = list(1L, 1:2),
      y = list(1L, 1:2)
    )
  )
})`

const rtdal007079Source0015 = `test_that("slide2_dfc() works", {
  x <- 1:2

  fn <- function(x, y) {
    if (length(x) == 1) {
      data.frame(x1 = x, y1 = y)
    } else {
      data.frame(x2 = x, y2 = y)
    }
  }

  expect_identical(
    slide2_dfc(x, x, fn, .before = 1),
    data.frame(
      x1 = c(1L, 1L),
      y1 = c(1L, 1L),
      x2 = 1:2,
      y2 = 1:2
    )
  )
})`

const rtdal007079Source0016 = "test_that(\"`.ptype = NULL` is size stable (#78)\", {\n  expect_length(slide2_vec(1:4, 1:4, ~.x, .step = 2), 4)\n  expect_length(slide2_vec(1:4, 1:4, ~1, .before = 1, .complete = TRUE), 4)\n})"

const rtdal007079Source0017 = "test_that(\"`slide2_vec()` falls back to `c()` method as required\", {\n  local_c_foobar()\n\n  expect_identical(\n    slide2_vec(1:3, 1:3, ~ foobar(.x), .ptype = foobar(integer())),\n    foobar(1:3)\n  )\n  expect_condition(\n    slide2_vec(1:3, 1:3, ~ foobar(.x), .ptype = foobar(integer())),\n    class = \"slider_c_foobar\"\n  )\n\n  expect_identical(slide2_vec(1:3, 1:3, ~ foobar(.x)), foobar(1:3))\n  expect_condition(\n    slide2_vec(1:3, 1:3, ~ foobar(.x)),\n    class = \"slider_c_foobar\"\n  )\n})"

const rtdal007079Source0018 = "test_that(\".step produces typed `NA` values\", {\n  expect_identical(slide2_int(1:3, 1:3, ~.x, .step = 2), c(1L, NA, 3L))\n  expect_identical(slide2_dbl(1:3, 1:3, ~.x, .step = 2), c(1, NA, 3))\n  expect_identical(\n    slide2_chr(c(\"a\", \"b\", \"c\"), 1:3, ~.x, .step = 2),\n    c(\"a\", NA, \"c\")\n  )\n  expect_identical(slide2_vec(1:3, 1:3, ~.x, .step = 2), c(1L, NA, 3L))\n  expect_identical(\n    slide2_vec(1:3, 1:3, ~.x, .step = 2, .ptype = integer()),\n    c(1L, NA, 3L)\n  )\n})"

const rtdal007079Source0019 = "test_that(\".complete produces typed `NA` values\", {\n  expect_identical(\n    slide2_int(1:3, 1:3, ~1L, .before = 1, .complete = TRUE),\n    c(NA, 1L, 1L)\n  )\n  expect_identical(\n    slide2_dbl(1:3, 1:3, ~1, .before = 1, .complete = TRUE),\n    c(NA, 1, 1)\n  )\n  expect_identical(\n    slide2_chr(1:3, 1:3, ~\"1\", .before = 1, .complete = TRUE),\n    c(NA, \"1\", \"1\")\n  )\n  expect_identical(\n    slide2_vec(1:3, 1:3, ~1, .before = 1, .complete = TRUE),\n    c(NA, 1, 1)\n  )\n  expect_identical(\n    slide2_vec(1:3, 1:3, ~1, .before = 1, .complete = TRUE, .ptype = integer()),\n    c(NA, 1L, 1L)\n  )\n})"

