const rtdal007082Source0001 = `test_that("integer before works", {
  x <- 1:4 + 0

  expect_identical(slide_sum(x, before = 1), c(1, 3, 5, 7))
  expect_identical(slide_sum(x, before = 2), c(1, 3, 6, 9))
})`

const rtdal007082Source0002 = `test_that("integer after works", {
  x <- 1:4 + 0

  expect_identical(slide_sum(x, after = 1), c(3, 5, 7, 4))
  expect_identical(slide_sum(x, after = 2), c(6, 9, 7, 4))
})`

const rtdal007082Source0003 = `test_that("negative before/after works", {
  x <- 1:4 + 0

  expect_identical(slide_sum(x, before = -1, after = 2), c(5, 7, 4, 0))
  expect_identical(slide_sum(x, before = 2, after = -1), c(0, 1, 3, 5))

  expect_identical(
    slide_sum(x, before = -1, after = 2, complete = TRUE),
    c(5, 7, NA, NA)
  )
  expect_identical(
    slide_sum(x, before = 2, after = -1, complete = TRUE),
    c(NA, NA, 3, 5)
  )
})`

const rtdal007082Source0004 = "test_that(\"`Inf` before/after works\", {\n  x <- 1:4 + 0\n\n  expect_identical(slide_sum(x, before = Inf), cumsum(x))\n  expect_identical(slide_sum(x, after = Inf), rev(cumsum(rev(x))))\n})"

const rtdal007082Source0005 = `test_that("step / complete works", {
  x <- 1:4 + 0

  expect_identical(slide_sum(x, before = 1, step = 2), c(1, NA, 5, NA))
  expect_identical(
    slide_sum(x, before = 1, step = 2, complete = TRUE),
    c(NA, 3, NA, 7)
  )
})`

const rtdal007082Source0006 = "test_that(\"NA / NaN results are correct\", {\n  x <- c(rep(1, 10), rep(NA, 10), 1:4)\n  y <- c(rep(NA, 10), rep(NaN, 10), 1:4)\n\n  # NA vs NaN results are platform dependent in `sum()` (especially on valgrind, #198),\n  # and order dependent (but probably stable) in the segment tree, so we can't actually\n  # robustly test the actual NA vs NaN results here. Instead we just use `expect_equal()`\n  # which tests the values and the fact that there is an NA-ish thing there.\n  expect_equal(\n    slide_sum(x, before = 3),\n    slide_dbl(x, sum, .before = 3)\n  )\n  expect_equal(\n    slide_sum(y, before = 3),\n    slide_dbl(y, sum, .before = 3)\n  )\n})"

const rtdal007082Source0007 = "test_that(\"`na_rm = TRUE` works\", {\n  x <- NA\n  y <- c(1, NA, 2, 3)\n\n  expect_identical(slide_sum(x, na_rm = TRUE), 0)\n  expect_identical(slide_sum(y, na_rm = TRUE, before = 1), c(1, 1, 2, 5))\n})"

const rtdal007082Source0008 = `test_that("Inf and -Inf results are correct", {
  x <- c(1, Inf, -Inf, 1)
  expect_identical(slide_sum(x, before = 1), c(1, Inf, NaN, -Inf))
})`

const rtdal007082Source0009 = `test_that("precision matches base R (long doubles) (#147) (#198)", {
  skip_on_cran()
  skip_if_no_long_double()
  x <- rep(1 / 7, 10)
  # Use equal, not identical, because even with long doubles some
  # platforms like Valgrind have differences out around the 17th digit
  expect_equal(sum(x), slide_sum(x, before = Inf)[[length(x)]])
})`

const rtdal007082Source0010 = "test_that(\"Inf + -Inf = NaN propagates with `na_rm = TRUE`\", {\n  x <- c(-Inf, Inf, rep(1, SEGMENT_TREE_FANOUT - 2L))\n  before <- SEGMENT_TREE_FANOUT - 1L\n\n  expect_identical(\n    slide_sum(x, before = before, na_rm = T),\n    slide_dbl(x, sum, .before = before, na_rm = T)\n  )\n})"

