const rtdal007144Source0006 = `as.SpatialPoints.ppp =  function(from) {
    mult <- 1
    if (!is.null(from$window$units) && !is.null(from$window$units$multiplier))
        mult <- from$window$units$multiplier
    mx <- mult*from$x
    storage.mode(mx) <- "double"
    my <- mult*from$y
    storage.mode(my) <- "double"
    crds <- cbind(mx, my)
    if (from$window$type == "rectangle") {
        ow <- from$window
        bbox <- rbind(mult*as.double(ow$xrange), mult*as.double(ow$yrange))
        colnames(bbox) <- c("min", "max")
    } else bbox <- NULL
    SpatialPoints(coords=crds, bbox=bbox)
}`

const rtdal007144Source0014 = `setAs("deldir", "SpatialPolygons", function(from) {
    cc = cbind(from$summary$x, from$summary$y)
	if (!requireNamespace("deldir", quietly = TRUE))
		stop("package deldir required")
    tm = deldir::triMat(from)
    fn = function(i) Polygons(list(Polygon(rbind(cc[tm[c(i, i[1]),], ]))), i)
    SpatialPolygons(lapply(1:nrow(tm), fn), proj4string = from@proj4string)
})`

